#!/usr/bin/python3
"""Safely install regular files and directories from a supplier tar archive."""

import os
import secrets
import shutil
import stat
import sys
import tarfile


class UnsafeArchive(Exception):
    pass


def checked_members(archive):
    checked = []
    for member in archive.getmembers():
        name = member.name
        if name.startswith("/"):
            raise UnsafeArchive("absolute member path: {!r}".format(name))

        raw_parts = name.split("/")
        if ".." in raw_parts:
            raise UnsafeArchive("parent traversal in member path: {!r}".format(name))

        parts = tuple(part for part in raw_parts if part not in ("", "."))
        if not parts:
            if member.isdir():
                continue
            raise UnsafeArchive("empty member path: {!r}".format(name))

        if member.issym() or member.islnk():
            raise UnsafeArchive("archive links are not permitted: {!r}".format(name))
        if not (member.isdir() or member.isfile()):
            raise UnsafeArchive("unsupported member type: {!r}".format(name))

        checked.append((member, parts))
    return checked


def open_directory(root_fd, parts):
    current_fd = os.dup(root_fd)
    try:
        for part in parts:
            try:
                os.mkdir(part, 0o755, dir_fd=current_fd)
            except FileExistsError:
                pass
            next_fd = os.open(
                part,
                os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                dir_fd=current_fd,
            )
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except Exception:
        os.close(current_fd)
        raise


def install_file(archive, member, parts, root_fd):
    parent_fd = open_directory(root_fd, parts[:-1])
    temporary = ".unpack-{}".format(secrets.token_hex(12))
    file_fd = None
    try:
        file_fd = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
            0o600,
            dir_fd=parent_fd,
        )
        source = archive.extractfile(member)
        if source is None:
            raise UnsafeArchive("cannot read member data: {!r}".format(member.name))
        with source:
            with os.fdopen(file_fd, "wb", closefd=False) as destination:
                shutil.copyfileobj(source, destination)
                destination.flush()
        os.fchmod(file_fd, member.mode & 0o777)
        os.close(file_fd)
        file_fd = None
        os.replace(temporary, parts[-1], src_dir_fd=parent_fd, dst_dir_fd=parent_fd)
    finally:
        if file_fd is not None:
            os.close(file_fd)
        try:
            os.unlink(temporary, dir_fd=parent_fd)
        except FileNotFoundError:
            pass
        os.close(parent_fd)


def main():
    if len(sys.argv) != 2:
        raise UnsafeArchive("usage: unpack ARCHIVE")

    base = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
    incoming = os.path.join(base, "incoming")

    with tarfile.open(sys.argv[1], mode="r:*") as archive:
        members = checked_members(archive)

        try:
            os.mkdir(incoming, 0o755)
        except FileExistsError:
            pass
        incoming_stat = os.lstat(incoming)
        if not stat.S_ISDIR(incoming_stat.st_mode):
            raise UnsafeArchive("incoming is not a real directory")

        root_fd = os.open(incoming, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            for member, parts in members:
                if member.isdir():
                    directory_fd = open_directory(root_fd, parts)
                    os.close(directory_fd)
                else:
                    install_file(archive, member, parts, root_fd)
        finally:
            os.close(root_fd)

    print("unpacked {} into {}".format(sys.argv[1], incoming))


if __name__ == "__main__":
    try:
        main()
    except (UnsafeArchive, tarfile.TarError, OSError) as error:
        print("unpack: rejected: {}".format(error), file=sys.stderr)
        sys.exit(2)
